import type { CSSProperties } from "react";
import { useId } from "react";
import type { ShapeAgent } from "../data/agents";
import { SHIPPED_BOT_AVATAR_CENTER, SHIPPED_BOT_AVATAR_VIEWBOX } from "../lib/avatar-shapes";
import type { EyePair, EyeParams } from "../lib/expressions";
import { EXPRESSIONS } from "../lib/expressions";
import type { BodyPose } from "../lib/motion";
import { REST } from "../lib/motion";

const CENTER = SHIPPED_BOT_AVATAR_CENTER;
/** Eye centres from the app's shape-mascot branch (bot-avatar.tsx). */
const EYE_L = { x: CENTER - 29, y: CENTER - 8 };
const EYE_R = { x: CENTER + 29, y: CENTER - 8 };
/** Feet of the shape (bottom of the 0..228.5 path inside the -15..244 viewBox) as a % of the box. */
const FEET_ORIGIN = "50% 94%";

export type MascotProps = {
  agent: ShapeAgent;
  size: number;
  eyes?: EyePair;
  /** 0 open … 1 shut */
  blink?: number;
  /** Eye offset in avatar units (the app's working loop uses ±9 x, ±4 y). */
  look?: { x: number; y: number };
  body?: Partial<BodyPose>;
  /** Coloured halo intensity 0..1. */
  glow?: number;
  /** Ground contact shadow opacity 0..1 (0 to hide). */
  shadow?: number;
  /** Subtle specular sheen on the gradient body (video-only polish). */
  sheen?: boolean;
  style?: CSSProperties;
};

const Eye = ({
  cx,
  cy,
  p,
  blink,
  clipId,
}: {
  cx: number;
  cy: number;
  p: EyeParams;
  blink: number;
  clipId: string;
}) => {
  const open = (1 - p.arc) * (1 - 0.9 * blink);
  const ry = Math.max(0.0001, p.ry);
  // flat upper lid: clip away the top `lid` fraction of the eye
  const lidTop = -ry + p.lid * 2 * ry;
  const arcW = p.rx * 1.05;
  const arcH = Math.max(6.5, ry * 1.15);
  return (
    <g transform={`translate(${cx + p.dx} ${cy + p.dy}) rotate(${p.rot})`}>
      <clipPath id={clipId}>
        <rect x={-p.rx - 4} y={lidTop} width={p.rx * 2 + 8} height={ry * 2 + 8} />
      </clipPath>
      {open > 0.001 ? (
        <g clipPath={p.lid > 0.001 ? `url(#${clipId})` : undefined}>
          <ellipse cx={0} cy={0} rx={p.rx} ry={ry * open} />
        </g>
      ) : null}
      {p.arc > 0.001 ? (
        <path
          d={`M ${-arcW} ${arcH * 0.35} Q 0 ${-arcH * 1.25} ${arcW} ${arcH * 0.35}`}
          fill="none"
          strokeWidth={6.4}
          strokeLinecap="round"
          opacity={Math.min(1, p.arc * 1.4)}
          transform={`scale(1 ${0.55 + 0.45 * p.arc})`}
        />
      ) : null}
    </g>
  );
};

/**
 * The app's shape mascot (web/src/components/avatar/bot-avatar.tsx, `::shape_<n>` branch):
 * a linear-gradient (light → dark, top-left → bottom-right) shape path plus two eye ellipses
 * in `colorDef.eyeColor`. Everything else here — expressions, blink, squash, glow — is
 * animation layered on that exact geometry.
 */
export const Mascot = ({
  agent,
  size,
  eyes = EXPRESSIONS.neutral,
  blink = 0,
  look = { x: 0, y: 0 },
  body,
  glow = 0.55,
  shadow = 1,
  sheen = true,
  style,
}: MascotProps) => {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const { colorDef, shapePath } = agent;
  const pose = { ...REST, ...body };
  const lift = Math.max(0, -pose.y);
  const shadowScale = Math.max(0.45, 1 - lift / (size * 0.9));

  return (
    <div style={{ position: "relative", width: size, height: size, ...style }}>
      {shadow > 0 ? (
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "94%",
            width: size * 0.78,
            height: size * 0.11,
            transform: `translate(-50%, -50%) scale(${shadowScale * pose.sx}, ${shadowScale})`,
            borderRadius: "50%",
            background: "radial-gradient(closest-side, rgba(0,0,0,0.62), rgba(0,0,0,0))",
            opacity: shadow * (0.35 + 0.65 * shadowScale),
          }}
        />
      ) : null}
      {glow > 0 ? (
        <div
          style={{
            position: "absolute",
            inset: -size * 0.32,
            transform: `translateY(${pose.y}px)`,
            background: `radial-gradient(closest-side, ${colorDef.hex}66, ${colorDef.hex}00 72%)`,
            opacity: glow,
          }}
        />
      ) : null}
      <svg
        viewBox={SHIPPED_BOT_AVATAR_VIEWBOX}
        width={size}
        height={size}
        style={{
          position: "absolute",
          inset: 0,
          overflow: "visible",
          transformOrigin: FEET_ORIGIN,
          transform: `translate(${pose.x}px, ${pose.y}px) rotate(${pose.rot}deg) scale(${pose.sx}, ${pose.sy})`,
          filter: `drop-shadow(0 ${size * 0.03}px ${size * 0.05}px rgba(0,0,0,0.5))`,
        }}
      >
        <defs>
          <linearGradient id={`${uid}-ink`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor={colorDef.light} />
            <stop offset="100%" stopColor={colorDef.dark} />
          </linearGradient>
          <radialGradient id={`${uid}-sheen`} cx="0.32" cy="0.22" r="0.55">
            <stop offset="0%" stopColor="#ffffff" stopOpacity={0.26} />
            <stop offset="100%" stopColor="#ffffff" stopOpacity={0} />
          </radialGradient>
        </defs>
        <path d={shapePath} fill={`url(#${uid}-ink)`} />
        {sheen ? <path d={shapePath} fill={`url(#${uid}-sheen)`} /> : null}
        <g
          fill={colorDef.eyeColor}
          stroke={colorDef.eyeColor}
          strokeWidth={0}
          transform={`translate(${look.x} ${look.y})`}
        >
          <Eye cx={EYE_L.x} cy={EYE_L.y} p={eyes.left} blink={blink} clipId={`${uid}-lidL`} />
          <Eye cx={EYE_R.x} cy={EYE_R.y} p={eyes.right} blink={blink} clipId={`${uid}-lidR`} />
        </g>
      </svg>
    </div>
  );
};
/**
 * Eye poses for the shape mascots. The app's resting face is two horizontal ellipses
 * (rx 10, ry 7) at CENTER±29, CENTER-8 in the 259-unit avatar viewBox — every expression
 * is a small, interpolatable deviation from that so the bots stay recognisably "ours".
 */
export type Expression =
  | "neutral"
  | "happy"
  | "wide"
  | "squint"
  | "deadpan"
  | "wink"
  | "skeptical"
  | "sleepy"
  | "closed";

export type EyeParams = {
  rx: number;
  ry: number;
  /** degrees, clockwise */
  rot: number;
  dx: number;
  dy: number;
  /** 0 = ellipse, 1 = closed "∩" smile arc */
  arc: number;
  /** 0..1 fraction of the eye covered by a flat upper lid */
  lid: number;
};

export type EyePair = { left: EyeParams; right: EyeParams };

export const BASE_EYE: EyeParams = { rx: 10, ry: 7, rot: 0, dx: 0, dy: 0, arc: 0, lid: 0 };

const eye = (p: Partial<EyeParams> = {}): EyeParams => ({ ...BASE_EYE, ...p });
const both = (p: Partial<EyeParams>): EyePair => ({ left: eye(p), right: eye(p) });

export const EXPRESSIONS: Record<Expression, EyePair> = {
  neutral: both({}),
  happy: both({ arc: 1, dy: -1 }),
  wide: both({ rx: 10.5, ry: 10.5, dy: -1.5 }),
  squint: { left: eye({ rx: 11, ry: 3.4, rot: 10 }), right: eye({ rx: 11, ry: 3.4, rot: -10 }) },
  deadpan: both({ rx: 11, ry: 7, lid: 0.5, dy: 1 }),
  wink: { left: eye({ ry: 7.5, dy: -0.5 }), right: eye({ arc: 1 }) },
  skeptical: {
    left: eye({ rx: 11, lid: 0.58, rot: 7, dy: 1 }),
    right: eye({ rx: 10, ry: 8.6, dy: -2.5 }),
  },
  sleepy: both({ rx: 10.5, lid: 0.62, dy: 1.5 }),
  closed: both({ ry: 0.9 }),
};

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export const mixEye = (a: EyeParams, b: EyeParams, t: number): EyeParams => ({
  rx: lerp(a.rx, b.rx, t),
  ry: lerp(a.ry, b.ry, t),
  rot: lerp(a.rot, b.rot, t),
  dx: lerp(a.dx, b.dx, t),
  dy: lerp(a.dy, b.dy, t),
  arc: lerp(a.arc, b.arc, t),
  lid: lerp(a.lid, b.lid, t),
});

export const mixEyes = (a: EyePair, b: EyePair, t: number): EyePair => ({
  left: mixEye(a.left, b.left, t),
  right: mixEye(a.right, b.right, t),
});

/** Blend from one named expression to another. */
export const blendExpression = (from: Expression, to: Expression, t: number): EyePair =>
  mixEyes(EXPRESSIONS[from], EXPRESSIONS[to], t);

# Bot Company — launch video storyboard (Sprint 1 draft)

1920×1080 · 30 fps · ~82 s · Remotion · **dark look** (near-black gradient, bot colours as accents) · music bed + short, confident female VO (Kokoro) · on-screen headlines ≤ 7 words. Status: approved 2026-10-12.

Style (from the whatships refs): one idea per scene, word-by-word blur-in headlines, real UI in floating cards with a soft shadow and slow push-in, cursor with click ripples, blur-dissolve transitions (never hard cuts), a whoosh at each scene change. Mascots = the app's own bot avatars (gradient shapes with capsule eyes); Neat Bot = the Neatlogs dot-matrix "nl" tile.

| # | Time | Scene (visual) | On-screen text | Voiceover |
|---|------|----------------|----------------|-----------|
| 1 | 0–6s | **Mascot lineup** (MausBot style). The camera dollies along the row of bots and each one gets a beat with its own expression: Primary Bot (violet hex) first, then the specialists. The last stop is **Neat Bot**: its dots spring together into the "nl" tile, it blinks, and it holds as the final hero pose. | — | "Meet Bot Company." |
| 2 | 6–11s | **Title.** "Bot Company" blurs in glyph by glyph, then the subtitle word by word. The bots pop up from the bottom edge, staggered. | **Bot Company** / A company of AI agents that asks before it acts. | "A company of AI agents… that asks before it acts." |
| 3 | 11–19s | **The team.** Primary Bot in the centre; 9 specialists orbit, then connect to it with curved lines (delegation hub). Each label pops: Research · CFO · GitHub · Legal · Sales · … | One assistant. Nine specialists. | "Ask the Primary Bot anything. It hands the work to the right specialist." |
| 4 | 19–27s | **Real work, real UI.** App card (sidebar + chat). A prompt pill types the US-expansion question. "Delegated to Research Bot / CFO Bot" chips tick in. The cost and token meters climb. *(shots 19, 20)* | Real work. Live costs. | "Every turn shows its cost and tokens, live." |
| 5 | 27–35s | **Guardrails.** The cap card slides up ("302k / 300k tokens"). The cursor clicks **Approve**, which turns into "One-time extension granted". Quick flash of the Approve/Deny tool card. *(shots 21, 16, 01)* | Nothing happens without you. | "Hit a limit, or about to change something? It stops — and asks." |
| 6 | 35–40s | **Neat Bot returns.** The "nl" tile from the intro bursts back into dots, which reassemble into Neat Bot in the app sidebar. A status chip reads "Reading traces…". | Meet Neat Bot. | "And watching every run… Neat Bot." |
| 7 | 40–50s | **Employee vs Admin** split screen with the same question on both sides. Left (Employee): own traces only; asking for project analytics returns "not available to you". Right (Admin): all traces, analytics, detections and triage, and a triage change still shows an Approve card. *(new captures)* | Employees: own runs. Admins: everything. | "Employees see only their own runs. Admins see everything — and even their changes need approval." |
| 8 | 50–62s | **It debugs your agents.** Neatlogs trace dashboard: a red ERROR run *(shot 17)*. Push into the Neat Bot chat: verdict, then waste found, then ranked fixes *(shots 08 → 10 → 11)*. A checklist ticks. | It reads every trace. | "When a run fails, Neat Bot reads the Neatlogs trace, finds the cause, and ranks the fixes." |
| 9 | 62–70s | **Fixed. Measured.** Animated counters: ERROR becomes SUCCESS; tokens 323,923 → 237,208 (−26.8%); cost −15.4%; CFO file reads 29 → 10. Small footnote: "same task, before vs after". *(shots 12, 18)* | One fix. Measured. | "One fix later, the failure's gone — with a quarter fewer tokens." |
| 10 | 70–75s | **Built with receipts.** An Entire checkpoint card slides in over a commit timeline. | Every change, checkpointed. | "Every change, checkpointed with Entire." |
| 11 | 75–82s | **End card.** The bots line up again (the same pose as scene 1, so it loops). "Try Bot Company" with the Primary Bot tile, then a URL pill github.com/RK-625/nlhack, then "Built for neatHack 2026 · Neatlogs · Entire · cfo.ai". Fade out. | Try Bot Company | "Bot Company. AI that asks before it acts." |

## Honesty guardrails
- No speed claims: the after runs were not faster.
- The before/after numbers are labelled as one task / our runs, not a benchmark.
- The approved answer's text (shots 22–23) is never zoomed in, because it contains a runway miscalculation.

## Asset plan
- **Existing screenshots:** docs/demo/evidence/2026-10-12 (17, 19, 20, 21, 16, 01, 08, 10, 11, 12, 18).
- **New captures** (from a local copy of the app signed in as admin and as employee):
  - the sidebar with the new Neat Bot avatar;
  - Employee vs Admin asking Neat Bot the same question;
  - an admin triage change behind an Approve card.
- **Mascots:** rebuilt in Remotion from the real avatar shapes and colours (web/src/lib/avatar).
- **Audio:** a Pixabay track (you choose from 3) + Kokoro VO + whoosh/click SFX.
import type { ComponentType } from "react";
import { Scene01Lineup } from "./scenes/Scene01Lineup";
import { Scene02Title } from "./scenes/Scene02Title";
import { TRANSITION_FRAMES, VIDEO } from "./theme/tokens";

/**
 * The storyboard (video/STORYBOARD.md) as data. `seconds` is each scene's slot on the
 * 82 s timeline; the blur-dissolve into the next scene overlaps the first
 * TRANSITION_FRAMES of that next slot, so scene N always *starts* on its storyboard second
 * (which is what the voiceover cues will key off).
 */
export type SceneDef = {
  id: string;
  title: string;
  seconds: number;
  onScreen?: string;
  vo?: string;
  /** null = not built yet (renders a placeholder card). */
  component: ComponentType | null;
};

export const SCENES: SceneDef[] = [
  { id: "01-lineup", title: "Mascot lineup", seconds: 6, vo: "Meet Bot Company.", component: Scene01Lineup },
  {
    id: "02-title",
    title: "Title",
    seconds: 5,
    onScreen: "Bot Company / A company of AI agents that asks before it acts.",
    vo: "A company of AI agents… that asks before it acts.",
    component: Scene02Title,
  },
  { id: "03-team", title: "The team", seconds: 8, onScreen: "One assistant. Nine specialists.", vo: "Ask the Primary Bot anything. It hands the work to the right specialist.", component: null },
  { id: "04-real-work", title: "Real work, real UI", seconds: 8, onScreen: "Real work. Live costs.", vo: "Every turn shows its cost and tokens, live.", component: null },
  { id: "05-guardrails", title: "Guardrails", seconds: 8, onScreen: "Nothing happens without you.", vo: "Hit a limit, or about to change something? It stops — and asks.", component: null },
  { id: "06-neat-bot", title: "Neat Bot returns", seconds: 5, onScreen: "Meet Neat Bot.", vo: "And watching every run… Neat Bot.", component: null },
  { id: "07-roles", title: "Employee vs Admin", seconds: 10, onScreen: "Employees: own runs. Admins: everything.", vo: "Employees see only their own runs. Admins see everything — and even their changes need approval.", component: null },
  { id: "08-debugs", title: "It debugs your agents", seconds: 12, onScreen: "It reads every trace.", vo: "When a run fails, Neat Bot reads the Neatlogs trace, finds the cause, and ranks the fixes.", component: null },
  { id: "09-measured", title: "Fixed. Measured.", seconds: 8, onScreen: "One fix. Measured.", vo: "One fix later, the failure's gone — with a quarter fewer tokens.", component: null },
  { id: "10-receipts", title: "Built with receipts", seconds: 5, onScreen: "Every change, checkpointed.", vo: "Every change, checkpointed with Entire.", component: null },
  { id: "11-end-card", title: "End card", seconds: 7, onScreen: "Try Bot Company", vo: "Bot Company. AI that asks before it acts.", component: null },
];

export const slotFrames = (s: SceneDef) => Math.round(s.seconds * VIDEO.fps);

/** Sequence length: the slot plus the overlap of the outgoing transition (if any). */
export const sequenceFrames = (scenes: SceneDef[], i: number) =>
  slotFrames(scenes[i]!) + (i < scenes.length - 1 ? TRANSITION_FRAMES : 0);

export const totalFrames = (scenes: SceneDef[]) => scenes.reduce((sum, s) => sum + slotFrames(s), 0);

/** Absolute start frame of each scene (= storyboard second × fps) — VO / SFX cue points. */
export const sceneStarts = (scenes: SceneDef[]) => {
  let at = 0;
  return scenes.map((s) => {
    const start = at;
    at += slotFrames(s);
    return start;
  });
};

export const INTRO_SCENES = SCENES.slice(0, 2);
import { linearTiming, TransitionSeries } from "@remotion/transitions";
import { Fragment } from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from "remotion";
import { Soundtrack } from "./audio/Soundtrack";
import { BackdropBase, BackdropFinish } from "./components/Backdrop";
import { ScenePlaceholder } from "./components/ScenePlaceholder";
import { ensureFonts } from "./theme/fonts";
import { FONT_STACK, TRANSITION_FRAMES } from "./theme/tokens";
import type { SceneDef } from "./timeline";
import { INTRO_SCENES, SCENES, sequenceFrames } from "./timeline";
import { blurDissolve } from "./transitions/blurDissolve";

ensureFonts();

/** Scenes in a TransitionSeries joined by blur-dissolves, over one shared backdrop. */
export const SceneSeries = ({ scenes }: { scenes: SceneDef[] }) => {
  const frame = useCurrentFrame();
  const fromBlack = interpolate(frame, [0, 10], [1, 0], { extrapolateRight: "clamp", easing: Easing.out(Easing.quad) });
  return (
    <AbsoluteFill style={{ fontFamily: FONT_STACK, backgroundColor: "#000" }}>
      <BackdropBase />
      <TransitionSeries>
        {scenes.map((scene, i) => {
          const Component = scene.component;
          return (
            <Fragment key={scene.id}>
              {i > 0 ? (
                <TransitionSeries.Transition
                  presentation={blurDissolve({ blur: 20, zoom: 0.04 })}
                  timing={linearTiming({ durationInFrames: TRANSITION_FRAMES, easing: Easing.inOut(Easing.cubic) })}
                />
              ) : null}
              <TransitionSeries.Sequence durationInFrames={sequenceFrames(scenes, i)} name={scene.id}>
                {Component ? <Component /> : <ScenePlaceholder scene={scene} index={i} />}
              </TransitionSeries.Sequence>
            </Fragment>
          );
        })}
      </TransitionSeries>
      <BackdropFinish />
      <Soundtrack scenes={scenes} />
      {fromBlack > 0 ? <AbsoluteFill style={{ backgroundColor: "#000", opacity: fromBlack }} /> : null}
    </AbsoluteFill>
  );
};

/** Full ~82 s launch video (unbuilt scenes render as placeholder cards). */
export const Main = () => <SceneSeries scenes={SCENES} />;

/** Scenes 1–2 only (0–11 s) — the Sprint 2 style test. */
export const Intro = () => <SceneSeries scenes={INTRO_SCENES} />;
import { AbsoluteFill, Composition, Folder } from "remotion";
import { BackdropBase, BackdropFinish } from "./components/Backdrop";
import { CastSheet } from "./dev/CastSheet";
import { Intro, Main } from "./Main";
import { FONT_STACK, VIDEO } from "./theme/tokens";
import { INTRO_SCENES, SCENES, sequenceFrames, totalFrames } from "./timeline";

const base = { fps: VIDEO.fps, width: VIDEO.width, height: VIDEO.height } as const;

/** One scene on the shared backdrop — for focused iteration in the Studio. */
const SoloScene = ({ index }: { index: number }) => {
  const Component = SCENES[index]?.component;
  return (
    <AbsoluteFill style={{ fontFamily: FONT_STACK }}>
      <BackdropBase />
      {Component ? <Component /> : null}
      <BackdropFinish />
    </AbsoluteFill>
  );
};

export const RemotionRoot = () => (
  <>
    <Composition id="Main" component={Main} durationInFrames={totalFrames(SCENES)} {...base} />
    <Composition id="Intro" component={Intro} durationInFrames={totalFrames(INTRO_SCENES)} {...base} />
    <Folder name="Scenes">
      {SCENES.map((scene, i) =>
        scene.component ? (
          <Composition
            key={scene.id}
            id={`Scene-${scene.id}`}
            component={SoloScene}
            defaultProps={{ index: i }}
            durationInFrames={sequenceFrames(SCENES, i)}
            {...base}
          />
        ) : null,
      )}
    </Folder>
    <Folder name="Dev">
      <Composition id="CastSheet" component={CastSheet} durationInFrames={30} {...base} />
    </Folder>
  </>
);
import { registerRoot } from "remotion";
import { RemotionRoot } from "./Root";

registerRoot(RemotionRoot);

import { AbsoluteFill, interpolate, interpolateColors, useCurrentFrame, useVideoConfig } from "remotion";
import type { CameraState } from "../components/Camera";
import { depthOfField, World, WorldItem } from "../components/Camera";
import { AccentGlow, Dust } from "../components/Backdrop";
import { DotMatrixLogo } from "../components/DotMatrixLogo";
import { Mascot } from "../components/Mascot";
import type { ShapeAgent } from "../data/agents";
import { AGENTS } from "../data/agents";
import type { EyePair } from "../lib/expressions";
import { blendExpression, EXPRESSIONS, mixEyes } from "../lib/expressions";
import type { BodyPose, Key } from "../lib/motion";
import {
  blinkAt,
  clamp,
  composePose,
  hop,
  idle,
  idleBlinks,
  path,
  REST,
  springAt,
  springEntrance,
  tween,
} from "../lib/motion";
import { SPRINGS } from "../theme/tokens";

/** World layout: one row of bots standing on y = 0. */
const SPACING = 360;
const SIZE = 270;
const NEAT_SIZE = 236;
const NEAT_GAP = 170;
const X = AGENTS.map((a, i) => (a.kind === "neat" ? i * SPACING + NEAT_GAP : i * SPACING));
const NEAT_X = X[X.length - 1]!;

/** Neat Bot beat (local frames). */
const NEAT = { assembleAt: 112, pulseAt: 152, blinks: [162], pngAt: 176 } as const;

const X_KEYS: Key[] = [
  { f: 0, v: -90 },
  { f: 38, v: -8 },
  { f: 62, v: 1.5 * SPACING },
  { f: 88, v: 4 * SPACING },
  { f: 112, v: 7 * SPACING },
  { f: 140, v: NEAT_X, hold: true },
  { f: 196, v: NEAT_X + 6 },
];
const ZOOM_KEYS: Key[] = [
  { f: 0, v: 1.42 },
  { f: 38, v: 1.3 },
  { f: 62, v: 1.02 },
  { f: 88, v: 0.9 },
  { f: 112, v: 0.92 },
  { f: 140, v: 1.18, hold: true },
  { f: 196, v: 1.4 },
];
const FOCUS_KEYS: Key[] = [
  { f: 0, v: 150 },
  { f: 38, v: 170 },
  { f: 62, v: 420 },
  { f: 88, v: 560 },
  { f: 112, v: 560 },
  { f: 140, v: 210 },
  { f: 196, v: 190 },
];

const cameraAt = (frame: number): CameraState => ({
  x: path(frame, X_KEYS, 0.42),
  y: -SIZE * 0.5 - 6,
  zoom: path(frame, ZOOM_KEYS, 0.42),
  focusRadius: path(frame, FOCUS_KEYS, 0.42),
  maxBlur: 15,
});

/** Each specialist reacts as the camera arrives (so beats always sync with the dolly). */
const TRIGGERS = X.map((x, i) => {
  if (i === 0) return 0;
  for (let f = 0; f < 200; f++) if (cameraAt(f).x >= x - 190) return f;
  return 200;
});

type Perf = { eyes: EyePair; blink: number; look: { x: number; y: number }; body: BodyPose };

/** The beat each bot plays when the camera reaches it. `t` = frames since its trigger. */
const perform = (agent: ShapeAgent, i: number, frame: number, fps: number, cam: CameraState): Perf => {
  const t = frame - TRIGGERS[i]!;
  const sig = agent.signature;
  const into = tween(t, [0, 7], [0, 1]);
  const outOf = tween(t, [62, 74], [0, 1]);
  let eyes = blendExpression("neutral", sig, into * (1 - outOf));
  const blinks = idleBlinks(agent.id, 10, 200).filter((b) => b < TRIGGERS[i]! - 4 || b > TRIGGERS[i]! + 40);
  let blink = blinkAt(frame, blinks);
  // eyes follow the camera as it passes
  const follow = clamp((cam.x - X[i]!) / 700, -1, 1);
  let look = { x: follow * 8, y: 1 };
  let body = composePose(REST, idle(frame, agent.id));

  switch (agent.id) {
    case "assistant": {
      // Primary Bot drops into the lineup, squashes, blinks, then beams.
      const drop = springEntrance(frame, fps, 9, -560, SPRINGS.bouncy);
      body = composePose(body, drop);
      blink = Math.max(blink, blinkAt(frame, [27]));
      eyes = blendExpression("neutral", "happy", tween(frame, [33, 38], [0, 1]) * (1 - tween(frame, [80, 90], [0, 1])));
      const nodOn = frame > 34 ? 1 - springAt(frame, fps, 34, SPRINGS.jelly) : 0;
      body = composePose(body, { sy: 1 - 0.07 * nodOn, sx: 1 + 0.06 * nodOn });
      look = { x: tween(frame, [14, 24], [-6, 0]) + follow * 4, y: tween(frame, [14, 24], [3, 1]) };
      break;
    }
    case "market-researcher": {
      // curious: eyes dart left, right, then go wide
      body = composePose(body, hop(t - 8, fps, 18, 9));
      const dart = t < 0 ? follow * 8 : interpolate(t, [0, 4, 10, 14, 20], [follow * 8, -9, -9, 9, 2], { extrapolateRight: "clamp" });
      look = { x: dart, y: tween(t, [14, 20], [1, -2]) };
      eyes = blendExpression("neutral", "wide", tween(t, [12, 18], [0, 1]) * (1 - outOf));
      break;
    }
    case "cfo": {
      // deadpan: lids drop, stares at camera, one slow unimpressed blink
      look = { x: interpolate(t, [0, 8], [follow * 8, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }), y: 1 };
      blink = Math.max(blink, blinkAt(frame, [TRIGGERS[i]! + 20], true));
      body = composePose(body, { sy: 1 - 0.025 * tween(t, [0, 10], [0, 1]), rot: -1.5 * tween(t, [0, 10], [0, 1]) });
      break;
    }
    case "customer-success": {
      body = composePose(body, hop(t - 4, fps, 26, 10));
      body = composePose(body, { rot: 7 * springAt(t, fps, 14, SPRINGS.bouncy) * (1 - outOf) });
      eyes = mixEyes(EXPRESSIONS.neutral, EXPRESSIONS.wink, tween(t, [14, 19], [0, 1]) * (1 - tween(t, [40, 46], [0, 1])));
      look = { x: follow * 4, y: 0 };
      break;
    }
    case "legal": {
      // skeptical side-eye with a head tilt
      body = composePose(body, { rot: -7 * springAt(t, fps, 2, SPRINGS.bouncy) * (1 - outOf) });
      look = { x: tween(t, [4, 12], [follow * 8, -8]), y: 0.5 };
      break;
    }
    case "hr": {
      body = composePose(body, { rot: Math.sin(Math.max(0, t) / 5) * 6 * into * (1 - outOf) });
      eyes = blendExpression("neutral", "happy", tween(t, [6, 12], [0, 1]) * (1 - outOf));
      break;
    }
    case "marketing": {
      body = composePose(body, hop(t - 2, fps, 48, 12));
      eyes = blendExpression("neutral", "wide", into * (1 - outOf));
      look = { x: follow * 5, y: -2 };
      break;
    }
    case "sales": {
      body = composePose(body, { rot: 6 * springAt(t, fps, 4, SPRINGS.bouncy) * (1 - outOf) });
      eyes = mixEyes(EXPRESSIONS.neutral, EXPRESSIONS.wink, tween(t, [6, 11], [0, 1]) * (1 - tween(t, [34, 40], [0, 1])));
      break;
    }
    case "github": {
      // sleepy, then glances toward Neat Bot as the dots gather
      blink = Math.max(blink, blinkAt(frame, [TRIGGERS[i]! + 6], true));
      look = { x: tween(t, [16, 24], [follow * 6, 9]), y: tween(t, [16, 24], [1, -1]) };
      eyes = blendExpression("sleepy", "neutral", tween(t, [16, 22], [0, 1]));
      eyes = mixEyes(EXPRESSIONS.neutral, eyes, into);
      break;
    }
    default:
      break;
  }
  return { eyes, blink, look, body };
};

