import type { TransitionPresentation, TransitionPresentationComponentProps } from "@remotion/transitions";
import { AbsoluteFill, interpolate } from "remotion";

export type BlurDissolveProps = {
  /** Peak blur in px at the midpoint. */
  blur?: number;
  /** Scale travel; both scenes drift forward for a sense of motion. */
  zoom?: number;
};

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const BlurDissolvePresentation = ({
  children,
  presentationDirection,
  presentationProgress: p,
  passedProps,
}: TransitionPresentationComponentProps<BlurDissolveProps>) => {
  const blur = passedProps.blur ?? 18;
  const zoom = passedProps.zoom ?? 0.04;
  const entering = presentationDirection === "entering";
  const style = entering
    ? {
        opacity: interpolate(p, [0.15, 0.85], [0, 1], CLAMP),
        filter: `blur(${blur * (1 - p)}px)`,
        transform: `scale(${1 - zoom + zoom * p})`,
      }
    : {
        opacity: interpolate(p, [0.15, 0.85], [1, 0], CLAMP),
        filter: `blur(${blur * p}px)`,
        transform: `scale(${1 + zoom * p})`,
      };
  return <AbsoluteFill style={style}>{children}</AbsoluteFill>;
};

/** Blur-dissolve: no hard cuts — outgoing scene blurs/fades forward, incoming resolves from blur. */
export const blurDissolve = (props: BlurDissolveProps = {}): TransitionPresentation<BlurDissolveProps> => ({
  component: BlurDissolvePresentation,
  props,
});
import type { SceneDef } from "../timeline";
import { sceneStarts } from "../timeline";

/**
 * AUDIO SLOT — intentionally silent in Sprint 2.
 *
 * A later sprint drops files into public/audio/ and renders them here, e.g.
 *   public/audio/music.mp3            Pixabay bed (user picks 1 of 3), ducked under VO
 *   public/audio/vo/<scene-id>.wav    Kokoro VO line per scene (text = SceneDef.vo)
 *   public/audio/sfx/whoosh.wav       on every scene change (cue = scene start)
 * using <Audio src={staticFile(...)} /> from "remotion" inside <Sequence from={cue}>.
 * Cue points come from voCues() so audio always follows the storyboard timing.
 */
export const voCues = (scenes: SceneDef[]) => {
  const starts = sceneStarts(scenes);
  return scenes.map((s, i) => ({ sceneId: s.id, from: starts[i]!, text: s.vo ?? "" }));
};

export const Soundtrack = (_props: { scenes: SceneDef[] }) => null;

import type { CSSProperties } from "react";
import { useId } from "react";
import { Easing, Img, interpolate, random, spring, staticFile } from "remotion";
import { NL_DOT_RADIUS, NL_DOTS, NL_SOURCE_SIZE, NL_TILE_COLORS } from "../assets/nl-dots";
import { bump, clamp, lerp } from "../lib/motion";
import { SPRINGS } from "../theme/tokens";

const S = NL_SOURCE_SIZE;
const C = S / 2;
const TILE_RADIUS = S * 0.22;

const ys = NL_DOTS.map(([, y]) => y);
const MIN_Y = Math.min(...ys);
const MAX_Y = Math.max(...ys);
const xs = NL_DOTS.map(([x]) => x);
const MARK_CX = (Math.min(...xs) + Math.max(...xs)) / 2;
const MARK_CY = (MIN_Y + MAX_Y) / 2;
const MAX_DIST = Math.max(...NL_DOTS.map(([x, y]) => Math.hypot(x - MARK_CX, y - MARK_CY)));

type Dot = {
  tx: number;
  ty: number;
  sx: number;
  sy: number;
  delay: number;
  swirl: number;
  twinkle: number;
  scale0: number;
};

/** Scatter positions are deterministic so every render (and every still) matches. */
const DOTS: Dot[] = NL_DOTS.map(([tx, ty], i) => {
  const angle = random(`nl-a-${i}`) * Math.PI * 2;
  const r = 70 + Math.pow(random(`nl-r-${i}`), 0.7) * 330;
  const d = Math.hypot(tx - MARK_CX, ty - MARK_CY) / MAX_DIST;
  return {
    tx,
    ty,
    sx: C + Math.cos(angle) * r,
    sy: C + Math.sin(angle) * r * 0.62,
    delay: d * 14 + random(`nl-j-${i}`) * 3,
    swirl: (random(`nl-s-${i}`) - 0.5) * 90,
    twinkle: random(`nl-t-${i}`) * Math.PI * 2,
    scale0: 0.5 + random(`nl-k-${i}`) * 1.1,
  };
});

export type DotMatrixLogoProps = {
  /** Rendered tile edge in px. */
  size: number;
  /** Frame (in the caller's timeline) to read. */
  frame: number;
  fps: number;
  /** Frame at which the scattered dots start springing home. Use -Infinity for "already formed". */
  assembleAt?: number;
  /** Frames at which the mark "blinks" (a top→bottom lid sweep across the dot rows). */
  blinks?: number[];
  /** Frame at which the real PNG tile cross-fades in over the vector rebuild. */
  pngAt?: number;
  /** Frame for a soft pulse ring. */
  pulseAt?: number;
  /** Glow strength 0..1 around the tile. */
  glow?: number;
  style?: CSSProperties;
};

/**
 * Neat Bot = the Neatlogs "nl" dot-matrix tile (web/src/assets/neatlogs-nl.png).
 * The dots are sampled from that PNG (scripts/extract-nl-dots.mjs) so the vector rebuild
 * lines up 1:1 with the real asset for the cross-fade.
 */
export const DotMatrixLogo = ({
  size,
  frame,
  fps,
  assembleAt = Number.NEGATIVE_INFINITY,
  blinks = [],
  pngAt,
  pulseAt,
  glow = 0.6,
  style,
}: DotMatrixLogoProps) => {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const formed = !Number.isFinite(assembleAt);
  const t = frame - (formed ? -1000 : assembleAt);

  // Tile body appears as the last dots land.
  const tileIn = formed ? 1 : spring({ frame: t - 16, fps, config: SPRINGS.smooth, durationInFrames: 18 });
  const png = pngAt === undefined ? 0 : interpolate(frame, [pngAt, pngAt + 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.quad),
  });
  const pulse = pulseAt === undefined ? 0 : Easing.out(Easing.cubic)(clamp((frame - pulseAt) / 26, 0, 1));
  const pulseOpacity = pulseAt === undefined || frame < pulseAt ? 0 : (1 - pulse) * 0.6;

  // Whole-mark squash during a blink, like the shape mascots.
  const blinkMark = Math.max(0, ...blinks.map((b) => bump(frame - b - 2, 3, 1, 4)));

  const arrived = DOTS.map((d) =>
    formed ? 1 : spring({ frame: t - d.delay, fps, config: SPRINGS.snappy, durationInFrames: 24 }),
  );
  const assembled = arrived.reduce((a, b) => a + Math.min(1, b), 0) / DOTS.length;

  return (
    <div style={{ position: "relative", width: size, height: size, ...style }}>
      {/* soft halo */}
      <div
        style={{
          position: "absolute",
          inset: -size * 0.45,
          background: "radial-gradient(closest-side, rgba(236,236,238,0.20), rgba(236,236,238,0) 70%)",
          opacity: glow * (0.35 + 0.65 * assembled),
        }}
      />
      {/* pulse ring */}
      {pulseOpacity > 0 ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            borderRadius: size * (TILE_RADIUS / S),
            border: `${Math.max(1.5, size * 0.008)}px solid rgba(255,255,255,0.9)`,
            transform: `scale(${1.02 + pulse * 0.5})`,
            opacity: pulseOpacity,
            boxShadow: "0 0 24px rgba(255,255,255,0.35)",
          }}
        />
      ) : null}
      <svg
        viewBox={`0 0 ${S} ${S}`}
        width={size}
        height={size}
        style={{
          position: "absolute",
          inset: 0,
          overflow: "visible",
          transformOrigin: "50% 50%",
          transform: `scale(${1 + blinkMark * 0.02}, ${1 - blinkMark * 0.035})`,
        }}
      >
        <defs>
          <linearGradient id={`${uid}-tile`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor={NL_TILE_COLORS.topLeft} />
            <stop offset="100%" stopColor={NL_TILE_COLORS.topRight} />
          </linearGradient>
          <filter id={`${uid}-dotglow`} x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="1.6" result="b" />
            <feMerge>
              <feMergeNode in="b" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        <g
          opacity={tileIn}
          transform={`translate(${C} ${C}) scale(${lerp(0.86, 1, tileIn)}) translate(${-C} ${-C})`}
        >
          <rect
            x={0}
            y={0}
            width={S}
            height={S}
            rx={TILE_RADIUS}
            fill={`url(#${uid}-tile)`}
            stroke="rgba(255,255,255,0.10)"
            strokeWidth={1.2}
          />
        </g>
        <g fill="#ffffff" filter={formed || assembled > 0.98 ? undefined : `url(#${uid}-dotglow)`}>
          {DOTS.map((d, i) => {
            const p = arrived[i] ?? 1;
            const pc = Math.min(1, p);
            // curved flight: a perpendicular swirl that vanishes on arrival
            const x = lerp(d.sx, d.tx, p);
            const y = lerp(d.sy, d.ty, p);
            const dx = d.tx - d.sx;
            const dy = d.ty - d.sy;
            const len = Math.hypot(dx, dy) || 1;
            const bend = Math.sin(Math.PI * pc) * (d.swirl / 100) * len * 0.25;
            const px = x + (-dy / len) * bend;
            const py = y + (dx / len) * bend;
            const drift = (1 - pc) * Math.sin(frame / 9 + d.twinkle) * 5;
            const r = NL_DOT_RADIUS * 0.94 * lerp(d.scale0, 1, pc);
            const twinkle = 0.45 + 0.35 * Math.sin(frame / 5 + d.twinkle);
            const opacity = lerp(twinkle, 1, pc);
            const rowDelay = ((d.ty - MIN_Y) / (MAX_Y - MIN_Y)) * 4;
            // LED-style blink: a lid sweeps top→bottom, each row of dots dips and relights
            const lid = Math.max(0, ...blinks.map((b) => bump(frame - b - rowDelay, 2, 1, 4)));
            return (
              <circle
                key={i}
                cx={px}
                cy={py + drift}
                r={r * (1 - 0.55 * lid)}
                opacity={opacity * (1 - 0.75 * lid)}
              />
            );
          })}
        </g>
      </svg>
      {png > 0 ? (
        <Img
          src={staticFile("neatlogs-nl.png")}
          style={{
            position: "absolute",
            inset: 0,
            width: size,
            height: size,
            borderRadius: size * (TILE_RADIUS / S),
            opacity: png,
          }}
        />
      ) : null}
    </div>
  );
};
import type { CSSProperties } from "react";
import { Easing, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { FONT_STACK, SPRINGS, TEXT_REVEAL } from "../theme/tokens";

export type TextSegment = {
  text: string;
  style?: CSSProperties;
  /** Extra frames before this segment starts (a beat for the voiceover). */
  pause?: number;
};

export type BlurInTextProps = {
  text: string | TextSegment[];
  /** Reveal per glyph (headlines) or per word (sentences). */
  by?: "glyph" | "word";
  /** Frame the first unit starts. */
  start?: number;
  stagger?: number;
  duration?: number;
  blur?: number;
  rise?: number;
  style?: CSSProperties;
};

type Unit = { key: string; text: string; style?: CSSProperties; delay: number; space: boolean };

/**
 * whatships-style reveal: each glyph/word fades in from blur(8px) and ~20px lower,
 * with a ~70 ms stagger. Spaces are kept as real text so line-breaking and spacing hold.
 */
export const BlurInText = ({
  text,
  by = "word",
  start = 0,
  stagger = TEXT_REVEAL.staggerFrames,
  duration = TEXT_REVEAL.durationFrames,
  blur = TEXT_REVEAL.blur,
  rise = TEXT_REVEAL.rise,
  style,
}: BlurInTextProps) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const segments: TextSegment[] = typeof text === "string" ? [{ text }] : text;

  const units: Unit[] = [];
  let index = 0;
  let extra = 0;
  segments.forEach((seg, s) => {
    extra += seg.pause ?? 0;
    const parts = by === "glyph" ? Array.from(seg.text) : seg.text.split(/(\s+)/).filter(Boolean);
    parts.forEach((part, p) => {
      const space = /^\s+$/.test(part);
      units.push({ key: `${s}-${p}`, text: part, style: seg.style, delay: index * stagger + extra, space });
      if (!space) index++;
    });
  });

  return (
    <span style={{ fontFamily: FONT_STACK, display: "inline-block", ...style }}>
      {units.map((u) => {
        if (u.space) {
          return (
            <span key={u.key} style={{ whiteSpace: "pre", ...u.style }}>
              {u.text}
            </span>
          );
        }
        const t = frame - start - u.delay;
        const p = interpolate(t, [0, duration], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.cubic),
        });
        const y = rise * (1 - spring({ frame: t, fps, config: SPRINGS.smooth, durationInFrames: duration + 6 }));
        const opacity = interpolate(t, [0, duration * 0.7], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        return (
          <span
            key={u.key}
            style={{
              display: "inline-block",
              whiteSpace: "pre",
              transform: `translateY(${y}px)`,
              filter: p < 1 ? `blur(${blur * (1 - p)}px)` : undefined,
              opacity,
              ...u.style,
            }}
          >
            {u.text}
          </span>
        );
      })}
    </span>
  );
};
import type { CSSProperties, ReactNode } from "react";
import { createContext, useContext } from "react";
import { AbsoluteFill } from "remotion";
import { clamp } from "../lib/motion";
import { VIDEO } from "../theme/tokens";

export type CameraState = {
  /** World point at the centre of the frame. */
  x: number;
  y: number;
  zoom: number;
  /** Screen-space radius (px) around the centre that stays in sharp focus. */
  focusRadius: number;
  /** Max depth-of-field blur in px. */
  maxBlur?: number;
};

const CameraContext = createContext<CameraState>({ x: 0, y: 0, zoom: 1, focusRadius: 400 });
export const useCamera = () => useContext(CameraContext);

/**
 * A 2D dolly camera: children are laid out in world coordinates and the camera
 * pans/zooms over them. Use <WorldItem> to place things and depthOfField() for focus.
 */
export const World = ({ camera, children }: { camera: CameraState; children: ReactNode }) => (
  <CameraContext.Provider value={camera}>
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: 0,
          height: 0,
          transformOrigin: "0 0",
          transform: `translate(${VIDEO.width / 2}px, ${VIDEO.height / 2}px) scale(${camera.zoom}) translate(${-camera.x}px, ${-camera.y}px)`,
        }}
      >
        {children}
      </div>
    </AbsoluteFill>
  </CameraContext.Provider>
);

/** Positions children so (x, y) is their anchor point (default: bottom-centre "feet"). */
export const WorldItem = ({
  x,
  y,
  anchor = "feet",
  style,
  children,
}: {
  x: number;
  y: number;
  anchor?: "feet" | "center";
  style?: CSSProperties;
  children: ReactNode;
}) => (
  <div
    style={{
      position: "absolute",
      left: x,
      top: y,
      transform: anchor === "feet" ? "translate(-50%, -100%)" : "translate(-50%, -50%)",
      ...style,
    }}
  >
    {children}
  </div>
);

/** Blur + dim for an object at world x, given the camera's focus band. */
export const depthOfField = (camera: CameraState, worldX: number) => {
  const screenDx = (worldX - camera.x) * camera.zoom;
  const off = Math.max(0, Math.abs(screenDx) - camera.focusRadius);
  const k = clamp(off / 520);
  return {
    screenDx,
    blur: (camera.maxBlur ?? 14) * Math.pow(k, 0.85),
    dim: 1 - 0.58 * k,
    focus: 1 - k,
  };
};

/** Slow push-in / drift wrapper for flat (non-world) scenes. */
export const Dolly = ({
  progress,
  from = 1,
  to = 1.05,
  driftY = 0,
  children,
}: {
  /** 0..1 through the shot. */
  progress: number;
  from?: number;
  to?: number;
  driftY?: number;
  children: ReactNode;
}) => (
  <AbsoluteFill
    style={{
      transform: `translateY(${driftY * progress}px) scale(${from + (to - from) * progress})`,
      transformOrigin: "50% 50%",
    }}
  >
    {children}
  </AbsoluteFill>
);
import { AbsoluteFill, random, useCurrentFrame } from "remotion";
import { COLORS } from "../theme/tokens";

/** Base near-black gradient shared by every scene (scenes render transparent on top). */
export const BackdropBase = () => (
  <AbsoluteFill
    style={{
      background: `radial-gradient(120% 95% at 50% 36%, ${COLORS.backgroundLift} 0%, #0e0f12 42%, ${COLORS.background} 70%, ${COLORS.backgroundDeep} 100%)`,
    }}
  />
);

/** Film grain + vignette on top of everything; the grain re-seeds every 2 frames for life. */
export const BackdropFinish = ({ grain = 0.055 }: { grain?: number }) => {
  const frame = useCurrentFrame();
  const seed = Math.floor(random(`grain-${Math.floor(frame / 2)}`) * 1000);
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill
        style={{
          background:
            "radial-gradient(ellipse 80% 75% at 50% 48%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.5) 100%)",
        }}
      />
      <AbsoluteFill style={{ opacity: grain, mixBlendMode: "overlay" }}>
        <svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
          <filter id="grain">
            <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed={seed} stitchTiles="stitch" />
            <feColorMatrix type="saturate" values="0" />
          </filter>
          <rect width="100%" height="100%" filter="url(#grain)" />
        </svg>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

/** A soft coloured light pool (e.g. the focal bot's colour bleeding into the dark). */
export const AccentGlow = ({
  color,
  x = 50,
  y = 55,
  w = 46,
  h = 52,
  opacity = 0.2,
}: {
  color: string;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
  opacity?: number;
}) => (
  <AbsoluteFill
    style={{
      background: `radial-gradient(${w}% ${h}% at ${x}% ${y}%, ${color}, rgba(0,0,0,0) 100%)`,
      opacity,
      mixBlendMode: "screen",
    }}
  />
);

/** Floating dust motes with parallax against a camera x (pass 0 for static scenes). */
export const Dust = ({
  count = 46,
  cameraX = 0,
  seed = "dust",
  opacity = 1,
}: {
  count?: number;
  cameraX?: number;
  seed?: string;
  opacity?: number;
}) => {
  const frame = useCurrentFrame();
  const W = 1920 + 200;
  return (
    <AbsoluteFill style={{ opacity, pointerEvents: "none" }}>
      {Array.from({ length: count }, (_, i) => {
        const depth = 0.15 + random(`${seed}-z-${i}`) * 0.85;
        const baseX = random(`${seed}-x-${i}`) * W;
        const baseY = random(`${seed}-y-${i}`) * 1080;
        const x = (((baseX - cameraX * depth * 0.6 + frame * 0.25 * depth) % W) + W) % W - 100;
        const y = baseY + Math.sin(frame / (40 + depth * 30) + i) * 10 - frame * 0.15 * depth;
        const r = 0.8 + depth * 2.2;
        const tw = 0.25 + 0.35 * (0.5 + 0.5 * Math.sin(frame / 14 + i * 1.7));
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x,
              top: ((y % 1080) + 1080) % 1080,
              width: r * 2,
              height: r * 2,
              borderRadius: "50%",
              background: "#ffffff",
              opacity: tw * depth * 0.55,
              filter: depth < 0.45 ? `blur(${(0.45 - depth) * 4}px)` : undefined,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};
import { AbsoluteFill } from "remotion";
