      </defs>
      <circle cx={24} cy={24} r={22} fill="none" stroke="url(#hub-ring)" strokeWidth={1.6} strokeLinecap="round" strokeDasharray="45 80" />
      <circle cx={46} cy={24} r={1.5} fill="#ffffff" />
    </svg>
