  { f: 132, cx: 1800, cy: 1049, zoom: 1.26 },
  { f: 152, cx: 1320, cy: 1226, zoom: 1.7, hold: true },
  { f: 178, cx: 1320, cy: 1226, zoom: 1.72 },
  // up to the live cost / token meters
  { f: 204, cx: 1796, cy: 435, zoom: 2.0 },
  { f: 255, cx: 1796, cy: 435, zoom: 2.08 },
