          color: "#1b1b1c",
          letterSpacing: "-0.01em",
        }}
      >
        {n === 0 ? <span style={{ color: "#9a9a97" }}>Message Primary Bot</span> : QUESTION.slice(0, n)}
        <span
          style={{
            display: "inline-block",
